Here's a self-contained HTML to-do list with add, complete, and delete actions, plus localStorage persistence. Task text is always treated as plain text.
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>To-Do List</title>
<style>
  :root {
    --bg: #f4f5f7;
    --card: #ffffff;
    --text: #1f2430;
    --muted: #7a8194;
    --accent: #4f6ef7;
    --accent-hover: #3d5ae0;
    --border: #e3e6ee;
    --danger: #e5484d;
    --done: #9aa1b1;
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    padding: 48px 16px;
    background: var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    -webkit-font-smoothing: antialiased;
  }

  .app {
    width: 100%;
    max-width: 520px;
    background: var(--card);
    border-radius: 16px;
    padding: 24px;
    box-shadow: 0 10px 30px rgba(20, 25, 45, 0.08);
  }

  h1 {
    margin: 0 0 18px;
    font-size: 20px;
    font-weight: 650;
    letter-spacing: -0.01em;
  }

  form {
    display: flex;
    gap: 8px;
    margin-bottom: 18px;
  }

  #todo-input {
    flex: 1;
    min-width: 0;
    padding: 12px 14px;
    font: inherit;
    font-size: 15px;
    color: inherit;
    background: #fbfcfe;
    border: 1px solid var(--border);
    border-radius: 10px;
    outline: none;
    transition: border-color .15s, box-shadow .15s;
  }

  #todo-input::placeholder { color: #a7adbd; }

  #todo-input:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(79, 110, 247, 0.15);
  }

  button {
    font: inherit;
    cursor: pointer;
    border: none;
    border-radius: 10px;
  }

  #add-btn {
    flex: none;
    padding: 12px 20px;
    font-size: 15px;
    font-weight: 600;
    color: #fff;
    background: var(--accent);
    transition: background .15s;
  }

  #add-btn:hover { background: var(--accent-hover); }

  #add-btn:focus-visible,
  .delete:focus-visible,
  #clear-done:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }

  ul {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .task {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 14px;
    background: #fbfcfe;
    border: 1px solid var(--border);
    border-radius: 10px;
  }

  .task .text {
    flex: 1;
    min-width: 0;
    line-height: 1.4;
    overflow-wrap: anywhere;
    cursor: pointer;
    transition: color .15s;
  }

  .task.done .text {
    color: var(--done);
    text-decoration: line-through;
  }

  .toggle {
    flex: none;
    width: 18px;
    height: 18px;
    margin: 0;
    accent-color: var(--accent);
    cursor: pointer;
  }

  .delete {
    flex: none;
    width: 28px;
    height: 28px;
    display: grid;
    place-items: center;
    font-size: 13px;
    line-height: 1;
    color: var(--muted);
    background: transparent;
    transition: background .15s, color .15s;
  }

  .delete:hover {
    background: #fdecec;
    color: var(--danger);
  }

  .empty {
    margin: 0;
    padding: 26px 0;
    text-align: center;
    font-size: 14px;
    color: var(--muted);
  }

  footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-top: 16px;
    padding-top: 16px;
    border-top: 1px solid var(--border);
    font-size: 13px;
    color: var(--muted);
    min-height: 20px;
  }

  #clear-done {
    padding: 6px 10px;
    font-size: 13px;
    color: var(--muted);
    background: transparent;
    transition: background .15s, color .15s;
  }

  #clear-done:hover:not(:disabled) {
    background: #f0f2f7;
    color: var(--text);
  }

  #clear-done:disabled {
    opacity: .45;
    cursor: default;
  }
</style>
</head>
<body>

<main class="app">
  <h1>To-Do</h1>

  <form id="todo-form" autocomplete="off">
    <input id="todo-input" type="text" maxlength="200" placeholder="What needs doing?" aria-label="New task">
    <button id="add-btn" type="submit">Add</button>
  </form>

  <ul id="todo-list"></ul>
  <p id="empty-state" class="empty">Nothing here yet — add your first task.</p>

  <footer>
    <span id="count" aria-live="polite"></span>
    <button id="clear-done" type="button" disabled>Clear completed</button>
  </footer>
</main>

<script>
(function () {
  'use strict';

  var STORAGE_KEY = 'todo-list.v1';

  var form        = document.getElementById('todo-form');
  var input       = document.getElementById('todo-input');
  var listEl      = document.getElementById('todo-list');
  var emptyEl     = document.getElementById('empty-state');
  var countEl     = document.getElementById('count');
  var clearDoneBtn = document.getElementById('clear-done');

  var tasks = [];
  var idCounter = 0;

  function uid() {
    idCounter += 1;
    return 't' + Date.now().toString(36) + '-' + idCounter;
  }

  /* ---------- persistence ---------- */

  function load() {
    var raw;
    try {
      raw = localStorage.getItem(STORAGE_KEY);
    } catch (e) {
      return []; // storage blocked (private mode, etc.)
    }
    if (!raw) return [];

    var data;
    try {
      data = JSON.parse(raw);
    } catch (e) {
      return []; // corrupted data — start fresh
    }
    if (!Array.isArray(data)) return [];

    var out = [];
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (!item || typeof item.text !== 'string') continue;
      out.push({
        id: (typeof item.id === 'string' && item.id) ? item.id : uid(),
        text: item.text,
        done: item.done === true
      });
    }
    return out;
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
    } catch (e) {
      // quota exceeded or storage unavailable — keep working in memory
    }
  }

  /* ---------- rendering ---------- */

  function render() {
    listEl.textContent = '';

    for (var i = 0; i < tasks.length; i++) {
      var task = tasks[i];

      var li = document.createElement('li');
      li.className = 'task' + (task.done ? ' done' : '');
      li.dataset.id = task.id;

      var toggle = document.createElement('input');
      toggle.type = 'checkbox';
      toggle.className = 'toggle';
      toggle.checked = task.done;
      toggle.setAttribute(
        'aria-label',
        (task.done ? 'Mark incomplete: ' : 'Mark complete: ') + task.text
      );

      var text = document.createElement('span');
      text.className = 'text';
      text.textContent = task.text;   // plain text only — never innerHTML
      text.title = task.text;

      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'delete';
      del.textContent = '\u2715';
      del.setAttribute('aria-label', 'Delete: ' + task.text);

      li.appendChild(toggle);
      li.appendChild(text);
      li.appendChild(del);
      listEl.appendChild(li);
    }

    var total = tasks.length;
    var done = 0;
    for (var j = 0; j < tasks.length; j++) {
      if (tasks[j].done) done++;
    }

    emptyEl.hidden = total !== 0;
    countEl.textContent = total === 0 ? '' : (total - done) + ' of ' + total + ' left';
    clearDoneBtn.disabled = done === 0;
  }

  /* ---------- actions ---------- */

  function addTask(rawText) {
    var text = rawText.trim();
    if (!text) return;
    tasks.push({ id: uid(), text: text, done: false });
    save();
    render();
  }

  function toggleTask(id) {
    for (var i = 0; i < tasks.length; i++) {
      if (tasks[i].id === id) {
        tasks[i].done = !tasks[i].done;
        save();
        render();
        return;
      }
    }
  }

  function deleteTask(id) {
    for (var i = 0; i < tasks.length; i++) {
      if (tasks[i].id === id) {
        tasks.splice(i, 1);
        save();
        render();
        return;
      }
    }
  }

  /* ---------- events ---------- */

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    addTask(input.value);
    input.value = '';
    input.focus();
  });

  listEl.addEventListener('click', function (e) {
    var li = e.target.closest ? e.target.closest('li.task') : null;
    if (!li) return;

    var id = li.dataset.id;
    var target = e.target;

    if (target.classList.contains('toggle') || target.classList.contains('text')) {
      toggleTask(id);
    } else if (target.classList.contains('delete')) {
      deleteTask(id);
    }
  });

  clearDoneBtn.addEventListener('click', function () {
    var remaining = [];
    for (var i = 0; i < tasks.length; i++) {
      if (!tasks[i].done) remaining.push(tasks[i]);
    }
    tasks = remaining;
    save();
    render();
  });

  /* ---------- init ---------- */

  tasks = load();
  render();
  input.focus();
})();
</script>

</body>
</html>
```
### Task Management & Persistence

Here's a quick walkthrough of the main interactions and how your tasks stay saved.

- **Add tasks** – Type in the input and press Enter or click Add. Empty or whitespace-only entries are ignored.
- **Complete tasks** – Click the checkbox or the task text to toggle its done state. Completed tasks get a strikethrough style.
- **Delete tasks** – Click the ✕ button on any task to remove it immediately.
- **Persistence** – Every change is saved to localStorage under the key `todo-list.v1`, so your list survives page reloads.
- **Plain text safety** – Task text is inserted with `textContent`, never `innerHTML`, so any HTML or script characters are displayed as literal text.
- **Footer controls** – The footer shows how many tasks are left and includes a Clear completed button that removes all done tasks at once.
---

**Optimization Tip:** You can adjust the `maxlength="200"` attribute on the input to change the maximum task length, and the `STORAGE_KEY` variable if you need a different localStorage key.

